-- 1. Native Better Auth D1 Tables
CREATE TABLE IF NOT EXISTS user (
    id VARCHAR(191) PRIMARY KEY,
    name TEXT NOT NULL,
    email VARCHAR(191) UNIQUE NOT NULL,
    emailVerified BIGINT NOT NULL DEFAULT 0,
    image TEXT,
    createdAt DATETIME(3) NOT NULL,
    updatedAt DATETIME(3) NOT NULL,
    role TEXT DEFAULT 'member', -- 'member', 'moderator', 'admin'
    tier TEXT DEFAULT 'free', -- 'free', 'kind', 'steady', 'supported'
    locale TEXT DEFAULT 'en' -- 'en', 'es', 'pt-BR'
);

CREATE TABLE IF NOT EXISTS session (
    id VARCHAR(191) PRIMARY KEY,
    expiresAt DATETIME(3) NOT NULL,
    token VARCHAR(191) UNIQUE NOT NULL,
    createdAt DATETIME(3) NOT NULL,
    updatedAt DATETIME(3) NOT NULL,
    ipAddress TEXT,
    userAgent TEXT,
    userId VARCHAR(191) NOT NULL REFERENCES user(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS account (
    id VARCHAR(191) PRIMARY KEY,
    accountId TEXT NOT NULL,
    providerId TEXT NOT NULL,
    userId VARCHAR(191) NOT NULL REFERENCES user(id) ON DELETE CASCADE,
    accessToken TEXT,
    refreshToken TEXT,
    idToken TEXT,
    accessTokenExpiresAt DATETIME(3),
    refreshTokenExpiresAt DATETIME(3),
    scope TEXT,
    password TEXT,
    createdAt DATETIME(3) NOT NULL,
    updatedAt DATETIME(3) NOT NULL
);

CREATE TABLE IF NOT EXISTS verification (
    id VARCHAR(191) PRIMARY KEY,
    identifier TEXT NOT NULL,
    value TEXT NOT NULL,
    expiresAt DATETIME(3) NOT NULL,
    createdAt DATETIME(3) NOT NULL,
    updatedAt DATETIME(3) NOT NULL
);

