    updated_at TEXT NOT NULL
);

-- 3. Daily Content & Favorites
CREATE TABLE IF NOT EXISTS affirmations (
    id VARCHAR(191) PRIMARY KEY,
    date VARCHAR(32) NOT NULL, -- YYYY-MM-DD
    locale VARCHAR(16) NOT NULL, -- 'en', 'es', 'pt-BR'
    affirmation TEXT NOT NULL,
    reflection TEXT NOT NULL,
    journal_prompt TEXT,
    grounding_practice_id TEXT,
    is_member_only BIGINT DEFAULT 0,
    created_at TEXT NOT NULL,
    UNIQUE(date, locale)
);

CREATE TABLE IF NOT EXISTS saved_favorites (
    id VARCHAR(191) PRIMARY KEY,
    user_id VARCHAR(191) NOT NULL REFERENCES user(id) ON DELETE CASCADE,
    item_type VARCHAR(64) NOT NULL, -- 'affirmation', 'practice', 'remedy', 'crystal', 'guide'
    item_id VARCHAR(191) NOT NULL,
    created_at TEXT NOT NULL,
    UNIQUE(user_id, item_type, item_id)
);

-- 4. Practices (12 Micro-practices)
CREATE TABLE IF NOT EXISTS practices (
    id VARCHAR(191) PRIMARY KEY,
    category TEXT NOT NULL, -- 'Grounding', 'Emotions', 'Self-Compassion', 'Relationships', 'Grief'
    duration_minutes BIGINT NOT NULL,
    slug VARCHAR(191) UNIQUE NOT NULL,
    is_premium BIGINT DEFAULT 0,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS practice_translations (
    practice_id VARCHAR(191) REFERENCES practices(id) ON DELETE CASCADE,
    locale VARCHAR(16) NOT NULL,
    title TEXT NOT NULL,
    subtitle TEXT NOT NULL,
    description TEXT NOT NULL,
    steps TEXT NOT NULL, -- JSON array of strings
    why_it_helps TEXT NOT NULL,
    PRIMARY KEY(practice_id, locale)
);

-- 5. Remedies & Holistic Care
CREATE TABLE IF NOT EXISTS remedies (
