-- 7. Courses, Modules, Lessons, Progress & Certificates
CREATE TABLE IF NOT EXISTS courses (
    id VARCHAR(191) PRIMARY KEY,
    slug VARCHAR(191) UNIQUE NOT NULL,
    is_premium BIGINT DEFAULT 1,
    level TEXT DEFAULT 'All levels',
    estimated_hours DECIMAL(10,2) DEFAULT 2.5,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS course_translations (
    course_id VARCHAR(191) REFERENCES courses(id) ON DELETE CASCADE,
    locale VARCHAR(16) NOT NULL,
    title TEXT NOT NULL,
    subtitle TEXT NOT NULL,
    description TEXT NOT NULL,
    learning_outcomes TEXT NOT NULL, -- JSON
    PRIMARY KEY(course_id, locale)
);

CREATE TABLE IF NOT EXISTS modules (
    id VARCHAR(191) PRIMARY KEY,
    course_id VARCHAR(191) REFERENCES courses(id) ON DELETE CASCADE,
    sort_order BIGINT NOT NULL,
    slug TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS module_translations (
    module_id VARCHAR(191) REFERENCES modules(id) ON DELETE CASCADE,
    locale VARCHAR(16) NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    PRIMARY KEY(module_id, locale)
);

CREATE TABLE IF NOT EXISTS lessons (
    id VARCHAR(191) PRIMARY KEY,
    module_id VARCHAR(191) REFERENCES modules(id) ON DELETE CASCADE,
    sort_order BIGINT NOT NULL,
    slug TEXT NOT NULL,
    duration_minutes BIGINT DEFAULT 15
);

CREATE TABLE IF NOT EXISTS lesson_translations (
    lesson_id VARCHAR(191) REFERENCES lessons(id) ON DELETE CASCADE,
    locale VARCHAR(16) NOT NULL,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    reflection_prompt TEXT,
    worksheet_reference TEXT,
    PRIMARY KEY(lesson_id, locale)
);

CREATE TABLE IF NOT EXISTS enrollments (
    id VARCHAR(191) PRIMARY KEY,
    user_id VARCHAR(191) NOT NULL REFERENCES user(id) ON DELETE CASCADE,
    course_id VARCHAR(191) NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
    status TEXT DEFAULT 'active', -- 'active', 'completed'
    enrolled_at TEXT NOT NULL,
    completed_at TEXT,
    UNIQUE(user_id, course_id)
);

CREATE TABLE IF NOT EXISTS lesson_progress (
    id VARCHAR(191) PRIMARY KEY,
    enrollment_id VARCHAR(191) NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE,
    lesson_id VARCHAR(191) NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
    completed BIGINT DEFAULT 1,
    reflection_note TEXT,
    updated_at TEXT NOT NULL,
    UNIQUE(enrollment_id, lesson_id)
);

CREATE TABLE IF NOT EXISTS certificates (
    id VARCHAR(191) PRIMARY KEY,
    enrollment_id VARCHAR(191) UNIQUE NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE,
    user_id VARCHAR(191) NOT NULL REFERENCES user(id) ON DELETE CASCADE,
    course_id VARCHAR(191) NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
    student_name TEXT NOT NULL,
    verification_code VARCHAR(191) UNIQUE NOT NULL,
    issued_at TEXT NOT NULL
);

-- 8. Quizzes & Self-Assessments
CREATE TABLE IF NOT EXISTS quizzes (
    id VARCHAR(191) PRIMARY KEY,
    slug VARCHAR(191) UNIQUE NOT NULL,
    tier_required TEXT DEFAULT 'steady', -- 'free', 'steady'
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS quiz_translations (
    quiz_id VARCHAR(191) REFERENCES quizzes(id) ON DELETE CASCADE,
    locale VARCHAR(16) NOT NULL,
    title TEXT NOT NULL,
    subtitle TEXT NOT NULL,
