-- 9. KindWell Circle Community
CREATE TABLE IF NOT EXISTS circle_spaces (
    id VARCHAR(191) PRIMARY KEY,
    slug VARCHAR(191) UNIQUE NOT NULL,
    sort_order BIGINT NOT NULL,
    icon TEXT
);

CREATE TABLE IF NOT EXISTS circle_space_translations (
    space_id VARCHAR(191) REFERENCES circle_spaces(id) ON DELETE CASCADE,
    locale VARCHAR(16) NOT NULL,
    name TEXT NOT NULL,
    description TEXT NOT NULL,
    PRIMARY KEY(space_id, locale)
);

CREATE TABLE IF NOT EXISTS circle_threads (
    id VARCHAR(191) PRIMARY KEY,
    space_id VARCHAR(191) NOT NULL REFERENCES circle_spaces(id) ON DELETE CASCADE,
    user_id VARCHAR(191) NOT NULL REFERENCES user(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    body TEXT NOT NULL,
    locale TEXT DEFAULT 'en',
    moderation_status TEXT DEFAULT 'approved', -- 'approved', 'flagged', 'hidden'
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS circle_posts (
    id VARCHAR(191) PRIMARY KEY,
    thread_id VARCHAR(191) NOT NULL REFERENCES circle_threads(id) ON DELETE CASCADE,
    user_id VARCHAR(191) NOT NULL REFERENCES user(id) ON DELETE CASCADE,
    body TEXT NOT NULL,
    moderation_status TEXT DEFAULT 'approved', -- 'approved', 'flagged', 'hidden'
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS circle_reports (
    id VARCHAR(191) PRIMARY KEY,
    reporter_id VARCHAR(191) NOT NULL REFERENCES user(id),
    reporter_name TEXT NOT NULL,
    reporter_email TEXT NOT NULL,
    thread_id VARCHAR(191) REFERENCES circle_threads(id),
    post_id VARCHAR(191) REFERENCES circle_posts(id),
    reason TEXT NOT NULL,
    status TEXT DEFAULT 'pending', -- 'pending', 'reviewed', 'dismissed'
    created_at TEXT NOT NULL
);

-- 10. Practitioners & Network
CREATE TABLE IF NOT EXISTS practitioners (
    id VARCHAR(191) PRIMARY KEY,
