    modality TEXT NOT NULL,
    credentials TEXT,
    location TEXT NOT NULL,
    is_remote BIGINT DEFAULT 1,
    is_in_person BIGINT DEFAULT 0,
    accepting_clients BIGINT DEFAULT 0,
