-- 11. Store & Orders
CREATE TABLE IF NOT EXISTS products (
    id VARCHAR(191) PRIMARY KEY,
    slug VARCHAR(191) UNIQUE NOT NULL,
    type TEXT NOT NULL, -- 'digital', 'printify_merch', 'direct_wellness'
    price DECIMAL(10,2) NOT NULL,
    member_price DECIMAL(10,2) NOT NULL, -- 15% discount for Supported tier
    currency TEXT DEFAULT 'USD',
    image_url TEXT NOT NULL,
    is_active BIGINT DEFAULT 1,
    digital_file_key TEXT,
    printify_blueprint_id TEXT,
    printify_print_provider_id TEXT,
    printify_product_id TEXT,
    printify_synced_at TEXT,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS product_translations (
    product_id VARCHAR(191) REFERENCES products(id) ON DELETE CASCADE,
    locale VARCHAR(16) NOT NULL,
    name TEXT NOT NULL,
    tagline TEXT NOT NULL,
    description TEXT NOT NULL,
    details TEXT NOT NULL, -- JSON array of strings
    PRIMARY KEY(product_id, locale)
);

CREATE TABLE IF NOT EXISTS orders (
    id VARCHAR(191) PRIMARY KEY,
    user_id VARCHAR(191) REFERENCES user(id),
    customer_email TEXT NOT NULL,
    customer_name TEXT NOT NULL,
    subtotal DECIMAL(10,2) NOT NULL,
    discount DECIMAL(10,2) DEFAULT 0,
    tax DECIMAL(10,2) DEFAULT 0,
    shipping DECIMAL(10,2) DEFAULT 0,
    total DECIMAL(10,2) NOT NULL,
    currency TEXT DEFAULT 'USD',
    payment_status TEXT DEFAULT 'pending', -- 'pending', 'completed', 'failed', 'refunded'
    payment_provider TEXT DEFAULT 'stripe',
    fulfillment_status TEXT DEFAULT 'pending', -- 'pending', 'processing', 'fulfilled', 'canceled', 'failed'
    stripe_session_id TEXT,
    stripe_payment_intent_id TEXT,
    paypal_order_id VARCHAR(191) UNIQUE,
    paypal_capture_id VARCHAR(191) UNIQUE,
    printify_payload TEXT,
    printify_order_id VARCHAR(191) UNIQUE,
    printify_status TEXT,
    tracking_number TEXT,
    tracking_url TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT
);

CREATE TABLE IF NOT EXISTS order_items (
    id VARCHAR(191) PRIMARY KEY,
    order_id VARCHAR(191) NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
    product_id VARCHAR(191) NOT NULL REFERENCES products(id),
    variant_title TEXT,
    quantity BIGINT NOT NULL,
    unit_price DECIMAL(10,2) NOT NULL,
    total_price DECIMAL(10,2) NOT NULL,
    download_token VARCHAR(191) UNIQUE,
    download_expires_at TEXT
);

CREATE TABLE IF NOT EXISTS digital_downloads (
    token VARCHAR(191) PRIMARY KEY,
    order_item_id VARCHAR(191) REFERENCES order_items(id),
    product_id VARCHAR(191) REFERENCES products(id),
    user_id VARCHAR(191) REFERENCES user(id),
    download_count BIGINT DEFAULT 0,
    max_downloads BIGINT DEFAULT 10,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL
);
-- 12. Printify catalog mappings and webhook receipts
CREATE TABLE IF NOT EXISTS printify_product_variants (
    product_id VARCHAR(191) NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    printify_product_id VARCHAR(191) NOT NULL,
    blueprint_id BIGINT,
    print_provider_id BIGINT,
    variant_id BIGINT NOT NULL,
    title TEXT NOT NULL,
    is_available BIGINT NOT NULL DEFAULT 1,
    production_cost DECIMAL(10,2),
    retail_price DECIMAL(10,2),
    shipping_json TEXT,
    hostinger_variant_id TEXT,
    updated_at TEXT NOT NULL,
    PRIMARY KEY (product_id, variant_id)
);

CREATE INDEX idx_printify_variants_lookup
    ON printify_product_variants (printify_product_id, variant_id);

CREATE TABLE IF NOT EXISTS printify_webhook_events (
    event_id VARCHAR(191) PRIMARY KEY,
    topic TEXT NOT NULL,
    printify_order_id VARCHAR(191),
    payload_hash TEXT,
    processed_at TEXT NOT NULL
);

CREATE INDEX idx_printify_webhook_order
    ON printify_webhook_events (printify_order_id);

CREATE TABLE IF NOT EXISTS paypal_webhook_events (
    event_id VARCHAR(191) PRIMARY KEY,
    event_type TEXT NOT NULL,
    resource_id VARCHAR(191),
    processed_at TEXT NOT NULL
);

CREATE INDEX idx_paypal_webhook_resource
    ON paypal_webhook_events (resource_id);

-- 13. Transactional email delivery metadata (message bodies are never stored)
CREATE TABLE IF NOT EXISTS transactional_email_events (
    id VARCHAR(191) PRIMARY KEY,
    event_key VARCHAR(191) UNIQUE NOT NULL,
    event_type TEXT NOT NULL,
    provider TEXT NOT NULL,
    recipient TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending', -- 'pending', 'sent', 'failed'
    provider_message_id TEXT,
    created_at TEXT NOT NULL,
    sent_at TEXT,
    updated_at TEXT NOT NULL
);


-- 12. Member Wellness Letters
CREATE TABLE IF NOT EXISTS wellness_letters (
    id VARCHAR(191) PRIMARY KEY,
    slug TEXT NOT NULL,
    locale VARCHAR(16) NOT NULL,
    title TEXT NOT NULL,
    publish_date TEXT NOT NULL,
    summary TEXT NOT NULL,
    content TEXT NOT NULL,
    created_at TEXT NOT NULL,
    UNIQUE(slug, locale)
);
